use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// Rust struct representation of the `repos` Postgres table (API_AND_STORAGE.md §2.2).
///
/// A `Repo` represents tenant-visible git repository metadata for a G5 org.
///
/// This struct is a passive data container — it contains no business logic,
/// no database queries, and no validation beyond what the Rust type system enforces.
#[derive(Debug, Clone, Serialize, Deserialize, sqlx::FromRow)]
pub struct Repo {
    /// UUID primary key, generated by `gen_random_uuid()`.
    pub id: Uuid,
    /// Foreign key to `orgs(id)`, CASCADE on delete.
    pub org_id: Uuid,
    /// Repository display name (e.g. `backend`).
    pub name: String,
    /// URL-safe identifier, unique within org. Format: `<org>/<slug>`.
    pub slug: String,
    /// HTTPS clone URL for the repository.
    pub git_url: String,
    /// Default branch name (e.g. `main`). NOT NULL with DEFAULT 'main'.
    pub default_branch: String,
    /// SCM provider: `'github'`, `'gitlab'`, or NULL for manually-added repos.
    pub provider: Option<String>,
    /// Provider's numeric/string repository ID. NULL for manually-added repos.
    pub provider_repo_id: Option<String>,
    /// Full name on the provider (e.g. `'acme/backend'` on GitHub). NULL for manually-added repos.
    pub provider_full_name: Option<String>,
    /// Row creation timestamp. NOT NULL with DEFAULT `now()`.
    pub created_at: DateTime<Utc>,
}
